<?php $form=isset($form)&&is_array($form)?$form:array();$selectedArea=isset($form['SpbbID'])?(int)$form['SpbbID']:($branches?(int)$branches[0]['SpbbID']:0); ?>
<div class="content-wrapper"><section class="content-header"><h1>Surat Permohonan Pengawasan Bunker</h1></section><section class="content"><?php if($error): ?><div class="alert alert-danger"><?= html_escape($error) ?></div><?php endif; ?>
<div class="box box-primary"><div class="box-body"><form method="post" id="bunker-form"><?php $this->load->view('pipeline/billing_token'); ?><div class="row">
<div class="col-sm-6 form-group"><label for="bunker-area">Area</label><select id="bunker-area" name="SpbbID" class="form-control" required><?php foreach($branches as $b): ?><option value="<?= (int)$b['SpbbID'] ?>" <?= $selectedArea===(int)$b['SpbbID']?'selected':'' ?>><?= html_escape($b['SpbbName']) ?></option><?php endforeach; ?></select></div>
<div class="col-sm-6 form-group"><label for="bunker-vessel">Kapal / Perusahaan</label><select id="bunker-vessel" name="VesselID" class="form-control" required><option value="">Pilih dari Basic Data</option><?php foreach($vessels as $v): ?><option data-area="<?= (int)$v['SpbbID'] ?>" value="<?= (int)$v['VesselID'] ?>" <?= isset($form['VesselID'])&&(int)$form['VesselID']===(int)$v['VesselID']?'selected':'' ?>><?= html_escape($v['VesselName'].' / '.$v['CompanyName']) ?></option><?php endforeach; ?></select></div>
<div class="col-sm-6 form-group"><label for="bunker-number">Nomor Surat Otomatis</label><input id="bunker-number" class="form-control" readonly placeholder="Pilih area, kapal dan tanggal surat"><small id="bunker-number-help" aria-live="polite">Urutan per area per bulan. Nomor final ditetapkan saat surat disimpan.</small></div>
<?php foreach(array('RequestDate'=>'Tanggal Surat','Place'=>'Tempat Surat','IssuerName'=>'Nama Perusahaan Penerbit','Recipient'=>'Kepada Yth. KSOP','RecipientPlace'=>'Kota Tujuan Surat','RemainingFuel'=>'Sisa BBM Saat Ini','PlannedLiters'=>'Rencana Bunker (liter)','Supplier'=>'Suplayer','OriginPort'=>'Datang Dari','ArrivalPort'=>'Kapal Tiba','FillingDate'=>'Rencana Tanggal Pengisian','Position'=>'Posisi Kapal','Captain'=>'Nakhoda','SignatoryTitle'=>'Jabatan Penandatangan','Signatory'=>'Nama Penandatangan') as $k=>$label):$date=in_array($k,array('RequestDate','FillingDate'),true); ?><div class="col-sm-6 form-group"><label for="bunker-<?= $k ?>"><?= $label ?></label><input id="bunker-<?= $k ?>" class="form-control" name="<?= $k ?>" type="<?= $date?'date':($k==='PlannedLiters'?'number':'text') ?>" maxlength="<?= $k==='Recipient'?500:200 ?>" <?= $k==='PlannedLiters'?'min="0.001" step="0.001"':'' ?> value="<?= html_escape(isset($form[$k])&&is_scalar($form[$k])?$form[$k]:($date?date('Y-m-d'):'')) ?>" required></div><?php endforeach; ?></div>
<p class="text-muted">Format: urutan/BBM/kode kapal/kode penerbit area/bulan Romawi/tahun. Contoh: 005/BBM/PL2/ASDP-PB/VIII/2026.</p><button class="btn btn-primary" id="bunker-save" disabled>Simpan &amp; Preview Surat</button></form></div></div>
<div class="box"><div class="box-body table-responsive"><table class="table"><tr><th>Nomor Surat</th><th>Tanggal</th><th>Area</th><th>Output</th></tr><?php foreach($requests as $r): ?><tr><td><?= html_escape($r['RequestNo']) ?></td><td><?= html_escape($r['RequestDate']) ?></td><td><?= (int)$r['SpbbID'] ?></td><td><a href="<?= site_url('Pipeline_setup/print_bunker/'.$r['BunkerID']) ?>" target="_blank">View / Cetak</a> &middot; <a href="<?= site_url('Pipeline_setup/print_bunker/'.$r['BunkerID']).'?pdf=1' ?>">PDF</a></td></tr><?php endforeach; ?><?php if(!$requests): ?><tr><td colspan="4">Belum ada surat permohonan.</td></tr><?php endif; ?></table></div></div></section></div>
<script>(function(){var area=document.getElementById('bunker-area'),vessel=document.getElementById('bunker-vessel'),date=document.getElementById('bunker-RequestDate'),number=document.getElementById('bunker-number'),help=document.getElementById('bunker-number-help'),save=document.getElementById('bunker-save'),request=0;var endpoint=<?= json_encode(site_url('Pipeline_setup/bunker_number_preview'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
function preview(){var serial=++request;number.value='';save.disabled=true;if(!area.value||!vessel.value||!date.value){help.textContent='Pilih area, kapal dan tanggal surat.';return;}help.textContent='Menghitung nomor surat...';fetch(endpoint+'?'+new URLSearchParams({area:area.value,vessel:vessel.value,date:date.value}).toString(),{credentials:'same-origin',cache:'no-store'}).then(function(response){return response.json();}).then(function(data){if(serial!==request)return;if(!data.ok){help.textContent=data.message||'Nomor surat belum tersedia.';return;}number.value=data.number;help.textContent='Pratinjau nomor. Nomor final dikunci saat penyimpanan agar tidak ganda.';save.disabled=false;}).catch(function(){if(serial===request)help.textContent='Nomor belum dapat dibaca. Periksa koneksi dan coba pilih kapal kembali.';});}
function filter(){Array.prototype.forEach.call(vessel.options,function(option){if(!option.value)return;option.hidden=option.disabled=option.dataset.area!==area.value;if(option.disabled&&option.selected)vessel.value='';});preview();}area.addEventListener('change',filter);vessel.addEventListener('change',preview);date.addEventListener('change',preview);document.getElementById('bunker-form').addEventListener('submit',function(){save.disabled=true;save.textContent='Menyimpan surat...';});filter();})();</script>
